() => {
  const searchInput = document.getElementById('twotabsearchtextbox');
  if (searchInput) {
    searchInput.focus();
    searchInput.value = 'portable air conditioner 300 sq ft energy efficient';
    searchInput.form.submit();
    return 'submitted: ' + searchInput.value;
  }
  return 'not found';
}

() => {
