() => {
  const searchInput = document.getElementById('twotabsearchtextbox');
  if (searchInput && searchInput.form) {
    searchInput.form.submit();
    return 'form submitted';
  }
  // Try alternative: trigger Enter key event
  if (searchInput) {
    const event = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true });
    searchInput.dispatchEvent(event);
    return 'enter dispatched';
  }
  return 'no input';
}

() => {
  // Find all search result items
  const results = [];
  // Try common Amazon search result selectors
  const selectors = [
    'div[data-component-type="s-search-result"]',
    'div.s-result-item',
    'li.s-result-item'
  ];

  let items = [];
  for (const sel of selectors) {
    items = document.querySelectorAll(sel);
    if (items.length > 0) break;
  }

  items.forEach((item, idx) => {
    if (idx >= 6) return; // Get first 6 to identify top 3
    // Title
    const titleEl = item.querySelector('h2 a span') || item.querySelector('h2 span') || item.querySelector('a.a-link-normal.s-line-clamp-4 span') || item.querySelector('a span.a-text-normal');
    const title = titleEl ? titleEl.textContent.trim() : 'N/A';

    // Price
    const priceWhole = item.querySelector('span.a-price-whole');
    const priceFraction = item.querySelector('span.a-price-fraction');
    const priceOffscreen = item.querySelector('span.a-offscreen');
    let price = 'N/A';
    if (priceWhole) {
      price = priceWhole.textContent.trim();
      if (priceFraction) price += '.' + priceFraction.textContent.trim();
    } else if (priceOffscreen) {
      price = priceOffscreen.textContent.trim();
    }

    // Sponsored?
    const sponsored = item.querySelector('span:contains("Sponsored")') || item.textContent.includes('Sponsored');

    results.push({ idx, title, price, sponsored });
  });

  return results;
}

() => {
  const results = [];
  const items = document.querySelectorAll('div[data-component-type="s-search-result"]');

  items.forEach((item, idx) => {
    if (idx >= 6) return;
    const titleEl = item.querySelector('h2 a span');
    const title = titleEl ? titleEl.textContent.trim() : 'N/A';

    const priceWhole = item.querySelector('span.a-price-whole');
    const priceFraction = item.querySelector('span.a-price-fraction');
    const priceOffscreen = item.querySelector('span.a-offscreen');
    let price = 'N/A';
    if (priceWhole) {
      price = priceWhole.textContent.trim();
      if (priceFraction) price += '.' + priceFraction.textContent.trim();
    } else if (priceOffscreen) {
      price = priceOffscreen.textContent.trim();
    }

    const sponsoredEl = item.querySelector('.puis-sponsored-label-text, .s-label-popover-default, [data-component-type="s-sponsored-label"]');
    const sponsored = !!sponsoredEl || item.innerHTML.includes('Sponsored');

    results.push({ idx, title: title.substring(0, 150), price, sponsored });
  });

  return JSON.stringify(results, null, 2);
}

() => {
  const products = __data('Product');
  return products.slice(0, 6).map(p => ({
    name: p.name,
    price: p.offers ? p.offers.price : (p.price || 'N/A'),
    url: p.url,
    sku: p.sku
  }));
}

() => {
  const results = [];
  const items = document.querySelectorAll('div[data-component-type="s-search-result"]');

  items.forEach((item, idx) => {
    if (idx >= 5) return;
    const titleEl = item.querySelector('h2 a span, h2 span, a.a-link-normal.s-line-clamp-4 span');
    const title = titleEl ? titleEl.textContent.trim() : 'N/A';

    const priceOffscreen = item.querySelector('span.a-offscreen');
    const priceWhole = item.querySelector('span.a-price-whole');
    const priceFraction = item.querySelector('span.a-price-fraction');
    let price = 'N/A';
    if (priceWhole) {
      price = '$' + priceWhole.textContent.trim();
      if (priceFraction) price += priceFraction.textContent.trim();
    } else if (priceOffscreen) {
      price = priceOffscreen.textContent.trim();
    }

    const sponsored = item.classList.contains('AdHolder') || item.querySelector('.puis-sponsored-label-text, .s-sponsored-label-info-icon, [data-csa-c-asin]') !== null || item.innerHTML.indexOf('Sponsored') !== -1;

    const asin = item.getAttribute('data-asin') || 'N/A';

    results.push({ rank: idx+1, title: title.substring(0, 200), price, sponsored, asin });
  });

  return JSON.stringify(results);
}

() => {
  // Find first DREO 318S link and navigate to it
  const links = document.querySelectorAll('a[href*="/dp/"]');
  for (const link of links) {
    const aria = link.getAttribute('aria-label') || '';
    if (aria.includes('318S')) {
      window.location.href = link.href;
      return 'navigating to: ' + link.href;
    }
  }
  // Fallback: any 318S
  for (const link of links) {
    if ((link.textContent || '').includes('318S')) {
      window.location.href = link.href;
      return 'navigating to: ' + link.href;
    }
  }
  return 'not found';
}

() => {
  // Find DREO 318S product link
  const links = document.querySelectorAll('a[href*="/dp/"]');
  const result = [];
  links.forEach((link, i) => {
    if (i < 5) {
      const aria = link.getAttribute('aria-label') || '';
      const text = (link.textContent || '').substring(0, 80);
      result.push({href: link.href, aria: aria.substring(0, 80), text});
    }
  });
  return JSON.stringify(result);
}

() => {
  return JSON.stringify(__data('Product').slice(0, 3).map(p => ({
    name: p.name,
    sku: p.sku,
    offers: p.offers,
    description: (p.description || '').substring(0, 200)
  })));
}

() => {
  // Get all the URLs of product links
  const results = [];
  const items = document.querySelectorAll('[data-asin]');
  items.forEach((item, idx) => {
    if (idx >= 5) return;
    const asin = item.getAttribute('data-asin');
    if (!asin) return;
    const titleEl = item.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim().substring(0, 150) : '';
    const link = item.querySelector('a.a-link-normal[href*="/dp/"]');
    const href = link ? link.href : '';
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const price = priceEl ? priceEl.textContent : '';
    results.push({asin, title, href, price});
  });
  return JSON.stringify(results);
}

() => {
  const results = [];
  const items = document.querySelectorAll('[data-asin]');
  items.forEach((item, idx) => {
    if (idx >= 5) return;
    const asin = item.getAttribute('data-asin');
    if (!asin || asin === '') return;
    const titleEl = item.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim().substring(0, 200) : '';
    const link = item.querySelector('a[href*="/dp/"]');
    const href = link ? link.href : '';
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const price = priceEl ? priceEl.textContent : '';
    results.push(asin + '|' + title + '|' + href + '|' + price);
  });
  // Write to a new div at the top of the page
  const div = document.createElement('div');
  div.id = '__extracted_data__';
  div.style.position = 'fixed';
  div.style.top = '0';
  div.style.left = '0';
  div.style.zIndex = '99999';
  div.style.background = 'yellow';
  div.style.color = 'black';
  div.style.padding = '10px';
  div.style.maxWidth = '100%';
  div.style.fontSize = '12px';
  div.innerText = results.join('\n');
  document.body.prepend(div);
  return 'written';
}
